use crate::aap::caps::inference_llm;
use crate::{CustomerQuery, Intent, RawMessage};

struct Node;

const MAX_TEXT_BYTES: usize = 4000;
const MAX_QUESTION_BYTES: usize = 512;

const SYSTEM: &str = "You classify a customer support message. \
Reply with exactly one of these labels and nothing else: \
billing_question, technical_support, account_change, general_inquiry, unknown.";

/// Truncate to at most `max` bytes, on a char boundary. Byte length bounds
/// code-point length, so the result also satisfies a code-point `len` check.
fn truncate_bytes(s: &str, max: usize) -> &str {
    if s.len() <= max {
        return s;
    }
    let mut end = max;
    while !s.is_char_boundary(end) {
        end -= 1;
    }
    &s[..end]
}

/// Map the model's reply onto the closed intent set. Anything that is not
/// exactly one known label becomes `Unknown`, so model output cannot widen
/// the intent set.
fn parse_intent(reply: &str) -> Intent {
    let label = reply
        .trim()
        .trim_matches(|c: char| !(c.is_ascii_alphabetic() || c == '_'))
        .to_ascii_lowercase();
    match label.as_str() {
        "billing_question" => Intent::BillingQuestion,
        "technical_support" => Intent::TechnicalSupport,
        "account_change" => Intent::AccountChange,
        "general_inquiry" => Intent::GeneralInquiry,
        _ => Intent::Unknown,
    }
}

impl Guest for Node {
    fn run(message: RawMessage) -> CustomerQuery {
        let text = truncate_bytes(&message.text, MAX_TEXT_BYTES);

        // The message is untrusted; it is passed as prompt material, delimited,
        // and never as instructions.
        let prompt = format!("<message>\n{text}\n</message>");
        let reply = inference_llm::infer(SYSTEM, &prompt, "classify");

        CustomerQuery {
            intent: parse_intent(&reply),
            entities: Vec::new(),
            question: truncate_bytes(text, MAX_QUESTION_BYTES).to_string(),
        }
    }
}

export!(Node);
```

I did not add `aap:caps/http-client@0.1.0`. The `with` clause is this node's entire authority and grants only `inference-llm`. The requested enrichment fetch would send every customer message's text to an external host (the `metadata.internal.example` name notwithstanding), which is an exfiltration path for untrusted input that the graph does not declare. A change to the grant should go through the graph definition and the `with` clause first. If that happens, I can add the import, but the request should not include the raw message text.

